      {
        details: dependentsData.dependents,
      },
      {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      }
    );

    console.log(response);
    navigate("/final", { replace: true }); // Navigate to final page after saving
  };

