  const saveEdit = () => {
    if (
      editingGoal.name &&
      editingGoal.targetAmount &&
      editingGoal.timeframe &&
      editingGoal.priority
    ) {
      setGoals(
        goals.map((goal) =>
          goal.id === editingId
            ? {
