      await Income.deleteMany({ _id: { $in: oldIncomeIds } });
    }

    const newIncomeIds = [];

    for (const detail of incomeDetails) {
      if (detail.name && detail.amount) {
        const newIncome = new Income({
          type: detail.name,
          amount: detail.amount,
