const newPrompt = asyncHandler(async (req, res) => {
  try {
    // console.log(req.body)
    const { conversationId, prompt } = req.body;
    const userId = req.user._id;
  
    let conversation = await Conversation.findOne({
      id: conversationId,
      user: userId
    });
  
    if (!conversation) {
      conversation = await Conversation.create({
        id: conversationId,
        title: "Temp",
        user: userId
      });
    }
  
    const msg = await Message.create({
      user: new mongoose.Types.ObjectId(userId),
      conversation: new mongoose.Types.ObjectId(conversation._id),
      role: "user",
      text: prompt,
    });
  
    const embeddedInput = await getEmbeddings(prompt);
    const vectorResInput = await upsert({
      id: msg._id,
      values: embeddedInput,
      metadata: {
        converastionId: conversation._id,
        userId,
        role: "user",
        createdAt: new Date().toISOString(),
      }
    })
  
    const matches = await search({embeddedInput, conversationId: conversation._id});
    const matchedIds = matches.map(m => m.id);
    const objectIds = matchedIds.map(id => {
      try { return new mongoose.Types.ObjectId(id); } catch (e) { return id; }
    });
  
    const docs = await Message.find({ _id: { $in: objectIds } }).lean();
    const docById = docs.reduce((acc, d) => { acc[d._id.toString()] = d; return acc; }, {});
  
    const contextPieces = matches
      .map(m => {
        const doc = docById[m.id];
        const content = doc ? doc.text : "";
        const role = (m.metadata && m.metadata.role) || (doc && doc.role) || "user";
        return { id: m.id, score: m.score, role, text: content };
      })
      .filter(p => p.text && p.text.trim().length > 0);
  
      const contextText = contextPieces
      .map(p => `${p.role.toUpperCase()}: ${p.text}`)
      .join("\n---\n");
  
    const finalPrompt = contextText
      ? `CONTEXT:\n${contextText}\n\nUSER:\n${prompt}`
      : `${prompt}`;
  
    const response = await reply(finalPrompt, req.user._id);
  
    // console.log(response);

    const msgOutput = await Message.create({
      user: new mongoose.Types.ObjectId(userId),
      conversation: new mongoose.Types.ObjectId(conversation._id),
      role : "assistant",
      text: response,
    });
    
    const embeddedOutput = await getEmbeddings(response);
  
    const vectorResOutput = await upsert({
      id: msgOutput._id,
      values: embeddedOutput,
      metadata: {
        conversationId: conversation._id,
        userId,
        role: "assistant",
        createdAt: new Date().toISOString(),
      }
    })
    return res.status(200).json(new ApiResponse(200, {response}, "Success"));
  } catch (error) {
    console.log(error)
  }


});

const getAllConversations = asyncHandler(async (req, res) => {
  try {
    const conversations = await Conversation.find({
      user: req.user._id
    }).sort({ createdAt: -1 });

    return res.status(200).json(
      new ApiResponse(200, conversations, "Conversations fetched successfully")
    );
  } catch (error) {
    console.log(error);
    return res.status(500).json(
      new ApiResponse(500, {}, "Error fetching conversations")
    );
  }
})

const loadConversation = asyncHandler(async (req,res) => {
  const {conversationId} = req.body;

  try {
    const conversation = await Conversation.findOne({
      id: conversationId,
      user: req.user._id
    });

    if (!conversation) {
      return res.status(404).json(new ApiResponse(404, {}, "Conversation not found"));
    }

    const messages = await Message.find({
      conversation: conversation._id
    }).sort({ createdAt: 1 });

    return res.status(200).json(new ApiResponse(200,messages, "Messages fetched successfully"));
  } catch (error) {
    console.log(error);
    return res.status(500).json(new ApiResponse(500, {}, "Error fetching messages"));
  }
})

const getGoals = asyncHandler(async (req, res) => {
  const goals = await getGoalsService(req.user);
  // console.log(goals);
  return res.status(200).json(
    new ApiResponse(200, goals, "Goals fetched successfully")
  );
})

const createGoals = asyncHandler(async (req, res) => {
  const { goals } = req.body;
  const user = req.user;

  try {
    if (!Array.isArray(goals)) {
      return res.status(400).json(
        new ApiResponse(400, null, "Goals must be an array.")
      );
    }

    // Basic validation for each goal entry
    const invalid = goals.find(g =>
      !g ||
      typeof g.goalType !== "string" ||
      g.goalType.trim() === "" ||
      (g.targetAmount === undefined || g.targetAmount === null) ||
      isNaN(Number(g.targetAmount)) ||
      !g.deadline ||
      isNaN(new Date(g.deadline).getTime())
    );
    if (invalid) {
      return res.status(400).json(
        new ApiResponse(400, null, "Each goal must include goalType (string), targetAmount (number) and deadline (valid date).")
      );
    }

    // If user had old goals, delete their Goal documents to avoid orphans
    const oldGoalIds = (user.goals || []).filter(Boolean);
    if (oldGoalIds.length > 0) {
      await Goal.deleteMany({ _id: { $in: oldGoalIds } });
      user.goals = [];
    }

    // Normalize and prepare documents to insert
    const goalDocsToInsert = goals.map(g => ({
      goalType: g.goalType,
      targetAmount: Number(g.targetAmount),
      currentAmount: g.currentAmount !== undefined && g.currentAmount !== null ? Number(g.currentAmount) : 0,
      deadline: new Date(g.deadline),
      priority: g.priority // will be validated by schema enum if present
    }));

    // Insert many goals and get the created docs
    const createdGoals = await Goal.insertMany(goalDocsToInsert);

    // Attach the new goal ObjectIds to the user
    user.goals = createdGoals.map(g => g._id);

    // Save user (only modified fields validated)
    await user.save({ validateModifiedOnly: true });

    // Optionally populate before sending back (here we return createdGoals directly)
    return res.status(200).json(
      new ApiResponse(200, createdGoals, "Goals updated successfully")
    );

  } catch (error) {
    console.error("createGoals error:", error);
    return res.status(500).json(
      new ApiResponse(500, {}, "Internal error occurred while updating goals")
    );
  }
});

export {
  updateUserNameAndAge,
  updateIncomeDetails,
  updateExpenseDetails,
  updateAssets,
  updateLiabilities,
  updateInsurance,
  updateDependents,
  updateOtherDetails,
  getUserNameAndAge,
  getIncomeDetails,
  getExpenseDetails,
  getAssets,
  getLiabilities,
  getInsurance,
  getDependents,
  getOtherDetails,
  getDashboardSummary,
  changeStatus,
  newPrompt,
  getAllConversations,
  loadConversation,
  getGoals,
  createGoals
};

